    83→/**
    84→ * Recovers stalled jobs on worker startup
    85→ * Finds jobs with RUNNING status older than threshold and marks them as FAILED
    86→ *
    87→ * Implements T049: Stalled job recovery
    88→ */
    89→async function recoverStalledJobs(): Promise<void> {
    90→  const threshold = new Date(Date.now() - STALLED_JOB_THRESHOLD_MS);
    91→
    92→  try {
    93→    // Find jobs that are marked as RUNNING but started more than 30 minutes ago
    94→    const stalledJobs = await prisma.job.findMany({
    95→      where: {
    96→        status: 'RUNNING',
    97→        startedAt: { lt: threshold },
    98→      },
    99→      select: {
   100→        id: true,
   101→        type: true,
   102→        startedAt: true,
   103→      },
   104→    });
   105→
   106→    if (stalledJobs.length === 0) {
   107→      logger.info(COMPONENT, 'No stalled jobs found on startup');
   108→      return;
   109→    }
   110→
   111→    logger.warn(COMPONENT, `Found ${stalledJobs.length} stalled jobs, recovering...`);
   112→
   113→    // Mark all stalled jobs as FAILED
   114→    const result = await prisma.job.updateMany({
   115→      where: {
   116→        id: { in: stalledJobs.map((j) => j.id) },
   117→      },
   118→      data: {
   119→        status: 'FAILED',
   120→        completedAt: new Date(),
   121→        error: 'Worker crashed or restarted - job was stalled',
   122→      },
   123→    });
   124→
   125→    logger.info(COMPONENT, `Recovered ${result.count} stalled jobs`, {
   126→      jobIds: stalledJobs.map((j) => j.id),
   127→      jobTypes: [...new Set(stalledJobs.map((j) => j.type))],
   128→    });
   129→  } catch (error) {
   130→    logger.error(COMPONENT, 'Failed to recover stalled jobs', {
   131→      error: error instanceof Error ? error.message : String(error),
   132→    });
   133→    // Don't throw - worker should continue starting
   134→  }
   135→}
