   141→/**
   142→ * Logs queue metrics every 60 seconds
   143→ * Implements T053: Worker stats monitoring
   144→ */
   145→async function logQueueStats(): Promise<void> {
   146→  try {
   147→    const health = await getQueuesHealth();
   148→
   149→    for (const [queueName, stats] of Object.entries(health)) {
   150→      logger.info(COMPONENT, `Queue stats: ${queueName}`, {
   151→        waiting: stats.waiting,
   152→        active: stats.active,
   153→        completed: stats.completed,
   154→        failed: stats.failed,
   155→        delayed: stats.delayed,
   156→        paused: stats.paused,
   157→      });
   158→    }
   159→
   160→    // Log total summary
   161→    const totals = Object.values(health).reduce(
   162→      (acc, stats) => ({
   163→        waiting: acc.waiting + stats.waiting,
   164→        active: acc.active + stats.active,
   165→        completed: acc.completed + stats.completed,
   166→        failed: acc.failed + stats.failed,
   167→      }),
   168→      { waiting: 0, active: 0, completed: 0, failed: 0 }
   169→    );
   170→
   171→    logger.info(COMPONENT, 'Queue stats summary', totals);
   172→  } catch (error) {
   173→    logger.error(COMPONENT, 'Failed to log queue stats', {
   174→      error: error instanceof Error ? error.message : String(error),
   175→    });
   176→  }
   177→}
