   185→      logger.error(COMPONENT, 'Stats monitoring error', {
   186→        error: err instanceof Error ? err.message : String(err),
   187→      });
   188→    });
   189→  }, STATS_INTERVAL_MS);
   190→
   191→  logger.info(COMPONENT, `Stats monitoring started (interval: ${STATS_INTERVAL_MS / 1000}s)`);
   192→}
